out = {
 "ch": 4,
 "title": "আমার লেখালেখি ও হিসাব",
 "pages": "৫২-৬৩",
 "mcq_total": len(cards),
 "type_counts": type_counts,
 "top_topics": top,
 "traps_summary": traps,
 "notes": {"sections": sections, "must": must},
 "cards": cards,
 "new_cards": nc,
 "flags": flags,
 "coverage": {"checked": len(cards), "unsupported": []},
 "spot_check": spot,
 "word_count": 0,
}

# word count
texts = []
for s in sections:
    for it in s['items']:
        texts += [it.get('f', ''), it.get('c', ''), it.get('trap', '')]
texts += must
wc = sum(len(t.split()) for t in texts)
out['word_count'] = wc

s = json.dumps(out, ensure_ascii=False, indent=1)
assert '—' not in s and '–' not in s, 'dash found'
open(BASE + 'build/ch4.json', 'w').write(s)
print('cards', len(cards), 'new', len(nc), 'wc', wc)
print(type_counts)
print([(t['topic'], t['count']) for t in top])
print('flags', [f['slide'] for f in flags])
print('st false', [c['slide'] for c in cards if not c['st']])
